namespace sv_79c6851cbac24c6c8569b3a39fb2c6a0.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts and notifies all
/// subscribers when the count changes.  Scoped lifetime ensures each
/// user circuit gets its own independent instance.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="CurrentLowStockCount"/> is updated.
    /// Subscribers must wrap StateHasChanged in InvokeAsync when the
    /// event fires from a background thread (e.g. timer-based polling).
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning items below minimum levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Updates the cached count and notifies all subscribers.
    /// </summary>
    public void UpdateCount(int count)
    {
        CurrentLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

