@page "/dashboard"
@rendermode InteractiveServer
@using sv_79c6851cbac24c6c8569b3a39fb2c6a0.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@Warehouse?.Name ?? "—"</p>
                <p class="text-muted">ID: @(Warehouse?.WarehouseId ?? "—")</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-1">
                    @if (AlertService.CurrentLowStockCount > 0)
                    {
                        <span class="text-danger">@AlertService.CurrentLowStockCount</span>
                    }
                    else
                    {
                        <span class="text-success">0</span>
                    }
                </p>
                <p class="text-muted">
                    Polling every 10 s &middot; Last check: @_lastCheck?.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;
    private DateTime? _lastCheck;

    protected override void OnInitialized()
    {
        // Subscribe so this component also refreshes when the shared service fires.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollAsync();   // immediate first fetch
            _ = StartPollingLoop();
        }
    }

    /// <summary>
    /// Runs when the cascaded warehouse value changes (user picks a new site).
    /// Immediately re-polls so the dashboard reflects the new warehouse.
    /// </summary>
    protected override async Task OnParametersSetAsync()
    {
        if (Warehouse is not null && _cts is not null)
        {
            await PollAsync();
        }
    }

    private async Task StartPollingLoop()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        try
        {
            while (await _timer.WaitForNextTickAsync(_cts.Token))
            {
                await PollAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAsync()
    {
        var warehouseId = Warehouse?.WarehouseId ?? "WH-A";
        var count = await AlertService.GetLowStockCountAsync(warehouseId);
        _lastCheck = DateTime.Now;

        // Push the new count into the shared service; this fires OnAlertCountChanged
        // which re-renders the sidebar AlertBadge AND this component.
        AlertService.UpdateCount(count);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
        AlertService.OnAlertCountChanged -= _handler;
    }
}

